  'match.four_tries_to_gain_10_yards': 'Four tries to gain 10 yards. Make it and you get four more; reach the end zone for a touchdown (6, plus a 1-point kick). On fourth down you usually punt or kick a field goal (3).',
  'match.the_clock': 'The clock',
  'match.the_clock_does_not_tick_on': 'The clock does not tick on its own: each play uses a few seconds, and if the last play ended with the clock <b>running</b> (tackled in bounds, no score), the time between plays comes off <b>when you snap</b>: {normal} s at normal tempo, {hurry} s in hurry-up, {milk} s milking it. The line under the score tells you which. An incompletion, a run out of bounds, a score or a timeout stops it: the next snap then costs nothing.',
  'match.timeout_spike_kneel_tempo': 'Timeout · Spike · Kneel · Tempo',
  'match.b_timeout_b_three_a_half': '<b>Timeout</b> (three a half) stops the clock so your next snap costs no time, on defense it is how you get the ball back from a team running the clock out. <b>Hurry-up</b> tempo cuts the runoff to {hurry} s for free; <b>milk clock</b> raises it to {milk} s when you are protecting a lead. <b>Spike</b> stops the clock for the price of a down (appears under a minute); <b>kneel</b> burns time when you are ahead, if the other side has no timeouts and less than {milk2} s is left, the clock runs out and the game is over.',
  'match.calling_plays': 'Calling plays',
  'match.pick_one_of_the_six_cards': 'Pick one of the six cards you set on Friday and press Snap; on defense pick a defense. ★ is the coach\'s suggestion; ✦ counters what you learned scouting; a grayed card needs a package you cannot field. <b>FG</b> kicks on any down when the kick is makeable.',
  'match.key_moments_full_coaching_auto_sim': 'Key Moments · Full Coaching · Auto · Sim',
  'match.b_key_moments_b_simulates_the': '<b>Key Moments</b> simulates the routine downs and stops for the big ones; <b>Full Coaching</b> lets you call every snap. <b>Auto</b> calls the coach\'s plays for you (1× or 2×) until you stop it. <b>Sim to key moment</b> jumps ahead; <b>Sim to final</b> ends the game at once.',
  'match.edges': 'Edges',
  'match.b_scheme_lock_b_all_starters': '<b>Scheme lock:</b> all starters on a side fitting the coordinator\'s scheme play with +{schemeLockEdge}. Training (T) and media day (+) lifts show on the pregame lineup. Abilities fire on the strip under the field. <b>Inspect:</b> before the snap, tap a monster in the formation (or an entry of the ability strip) for its stamina, status and ability, and what is protecting it.',
  'match.type_matchups': 'Type matchups',
  'match.before_the_snap_a_green_b': 'Before the snap, a green <b>▲</b> or amber <b>▼</b> beside one of your monsters means a type advantage or disadvantage against the monster he is expected to face. Tap it to see the matchup. In the play, the edge (+4% or −4% on his side of a block, tackle, sack, separation or contested catch; Dragon +2% against neutral types) counts only against the monster he really meets. It never changes ratings. The Type Chart is under More and on every monster card.',
