  // ── Beast Clash screens and arena [clash]
  'clash.watch_battle': 'Watch battle',
  'clash.watch_every_exchange_your_monsters_enter': 'Watch every exchange. Your monsters enter in the order you set.',
  'clash.skip_to_results': 'Skip to results',
  'clash.the_same_battle_resolved_instantly_skipping': 'The same battle, resolved instantly. Skipping never changes who wins.',
  'clash.b_beast_clash_b_is_a': '<b>Beast Clash</b> is a monster battle. Each side lines up its monsters in an order of entry. <b>One active fighter per side</b> trades strikes; the reserves wait and act only through abilities that name them (a reserve relay, a rescue, a commanded strike). When the active monster is knocked out, the next in line steps up with the battle as it stands (health, shields and statuses carry on). The last side standing wins, or the side with more health left after 30 exchanges.',
  'clash.b_rotations_b_after_both_fighters': '<b>Rotations.</b> After both fighters have acted, a side may rotate its active monster out for a reserve (at most once every four exchanges). In <b>Watch battle</b> you are asked at each legal rotation: <b>Stay in</b>, bring in a reserve, or <b>Auto for the rest</b> of this battle (the game\'s own rotation policy, the one the other side uses). A monster that rotates in by choice acts at half strength on its first turn. Knockout replacements and forced rotations carry no penalty.',
  'clash.b_watch_battle_b_shows_every': '<b>Watch battle</b> shows every exchange at the speed you choose and asks you about rotations. <b>Skip to results</b> plays the battle instantly with the automatic rotation policy on your side. Neither is a worse chance of winning: a Watch battle in which you choose Auto at the first prompt is the very same battle as Skip.',
  'clash.b_statuses_b_a_monster_carries': '<b>Statuses.</b> A monster carries one shared status at a time (Shielded, Guarded, Empowered, Weakened, Slowed, Stunned, Confused ...). In the pregame Clash and the overtime Clash, statuses carry into and out of the football game; a standalone Tuesday battle clears them at its end.',
  'clash.b_type_edges_b_next_to': '<b>Type edges:</b> ▲ next to a monster means its element hits the one in front of it harder; ▼ means it hits softer. Put a monster with ▲ in front, and keep your toughest for last.',
  'clash.b_tuesday_encounters_b_the_monster': '<b>Tuesday encounters:</b> the monster you chose fights beside two wild companions. They are matched to your club\'s strength and cannot be signed; only the monster you chose can join you.',
  'clash.b_skipping_a_tuesday_encounter_b': '<b>Skipping a Tuesday encounter</b> is different: no battle happens, so there is no chance to sign that monster this week. Nothing else is lost.',
  'clash.monsters_that_battle_earn_a_little': 'Monsters that battle earn a little experience and get slightly tired. Injured monsters sit out.',
  'clash.tuesday_beast_clash': 'Tuesday · Beast Clash',
  'clash.skip_encounter': 'Skip encounter',
  'clash.skipping_the_encounter_means_no_battle': 'Skipping the encounter means no battle and no chance to sign this monster this week. Nothing else is lost: no morale, no board confidence, no progress.',
  'clash.encounter_skipped_on_to_wednesday': 'Encounter skipped. On to Wednesday.',
  'clash.continue_to_wednesday': 'Continue to Wednesday',
