  'dialogue.once_you_beat_the_dragon_once': 'Once. You beat the dragon once. The dragon remembers.',
  'dialogue.i_have_waited_all_year_for': 'I have waited all year for this game.',
  'dialogue.the_wyrm_badge_was_never_meant': 'The Wyrm Badge was never meant to leave this stadium.',
  'dialogue.hold_it_tight_it_is_coming': 'Hold it tight. It is coming home.',
  'dialogue.so_you_are_the_one_they_2': 'So you are the one they talk about. Now I know why. The Wyrm Badge is yours.',
  'dialogue.the_dragon_remembers_every_scar_this': 'The dragon remembers every scar. This one he will remember with respect.',
  'dialogue.division_rivals_same_rebuild_different_owners': 'Division rivals. Same rebuild, different owners. Let’s see who got it right.',
  'dialogue.ill_be_honest_i_bet_the': 'I’ll be honest: I bet the board you would finish below us.',
  'dialogue.we_beat_you_last_time_everyone': 'We beat you last time. Everyone in the division noticed.',
  'dialogue.still_running_the_same_six_plays': 'Still running the same six plays? Good.',
