  // ── Achievements and commissioner calls [achievements]
  'achievements.first_blood': 'First blood',
  'achievements.win_your_first_game_with_a': 'Win your first game with a franchise.',
  'achievements.one_i_keep_a_tally_of': 'One. I keep a tally of every GM’s first win, some take a month, some take a season. Yours is on the books. Noted.',
  'achievements.nobody_remembers_the_first_one_try': 'Nobody remembers the first one, {first}. Try to make the next few harder to forget.',
  'achievements.a_word_from': 'A word from {rival}',
  'achievements.beat_your_rival_club_for_the': 'Beat your rival club for the first time.',
  'achievements.so_you_took_one_off_us': 'So you took one off us. Enjoy the night. I’ve lost to better clubs than yours and I still have the job.',
  'achievements.heres_a_tip_free_of_charge': 'Here’s a tip, free of charge: the second one is the one that matters. Nobody gets it.',
  'achievements.the_sweep': 'The sweep',
  'achievements.beat_your_rival_twice_in_one': 'Beat your rival twice in one season without losing to them.',
  'achievements.twice_in_one_season': 'Twice. In one season.',
  'achievements.i_dont_make_calls_like_this': 'I don’t make calls like this. My staff told me not to. I want you to know that I know, and that next year is a long way off.',
  'achievements.the_first_badge': 'The first badge',
  'achievements.win_your_first_gym_badge': 'Win your first gym badge.',
  'achievements.a_gym_badge_the_gym_coaches': 'A gym badge. The gym coaches don’t lose those lightly, and they don’t forget who took one.',
  'achievements.seven_left_and_every_one_of': 'Seven left, and every one of them has now watched your tape. I’d call that the price of success, but you already know that.',
  'achievements.four_of_eight': 'Four of eight',
  'achievements.hold_four_of_the_eight_gym': 'Hold four of the eight gym badges.',
  'achievements.half_the_gyms_the_last_gm': 'Half the gyms. The last GM who held four badges held them for six seasons before the fifth. I mention it only so you know what the other half costs.',
  'achievements.all_eight': 'All eight',
  'achievements.hold_all_eight_gym_badges': 'Hold all eight gym badges.',
  'achievements.to_the_general_manager_of': 'TO THE GENERAL MANAGER OF {CLUB}:',
  'achievements.eight_of_eight_the_gyms_are': 'EIGHT OF EIGHT. THE GYMS ARE YOURS.',
  'achievements.the_board_has_seen_this_twice': 'THE BOARD HAS SEEN THIS TWICE IN THE HISTORY OF THE LEAGUE. IT DOES NOT CONGRATULATE. IT RECORDS.',
  'achievements.the_board': 'THE BOARD',
  'achievements.a_winning_season': 'A winning season',
  'achievements.finish_your_first_winning_season': 'Finish your first winning season.',
  'achievements.a_winning_season_2': '{record}. A winning season.',
  'achievements.ill_be_honest_with_you_when': 'I’ll be honest with you, {first}: when you sat in my office I gave you three years to get here. This is happening very fast.',
  'achievements.the_board_will_have_noticed_the': 'The Board will have noticed. The Board notices everything. That is not always good news.',
  'achievements.perfect': 'Perfect',
  'achievements.go_unbeaten_through_a_regular_season': 'Go unbeaten through a regular season.',
  'achievements.nine_and_oh_i_have_the': 'Nine and oh. I have the sheet in front of me and I keep reading it.',
  'achievements.i_wont_say_its_never_been': 'I won’t say it’s never been done. I will say that nobody who did it was still in the job five years later. The league does not like being embarrassed.',
  'achievements.the_playoffs': 'The playoffs',
  'achievements.make_the_playoffs_for_the_first': 'Make the playoffs for the first time.',
  'achievements.youre_in_eight_clubs_three_rounds': 'You’re in. Eight clubs, three rounds, no second chances.',
  'achievements.the_regular_season_is_over_which': 'The regular season is over, which means the Board stops reading your record and starts reading the bracket. Different document. Same Board.',
  'achievements.conference_champions': 'Conference champions',
  'achievements.win_a_conference_championship': 'Win a conference championship.',
  'achievements.conference_champions_i_watched_the_whole': 'Conference champions. I watched the whole thing. I’d like to say I was rooting for the other side, but I was rooting for the other side.',
  'achievements.one_more_you_know_what_the': 'One more. You know what the Beast Bowl does to GMs who lose it? Nothing. That’s the part that eats you.',
  'achievements.beast_bowl_champions': 'Beast Bowl champions',
  'achievements.win_the_beast_bowl': 'Win the Beast Bowl.',
  'achievements.the_board_acknowledges_the_beast_bowl': 'THE BOARD ACKNOWLEDGES THE {YEAR} BEAST BOWL.',
  'achievements.you_will_be_asked_for_another': 'YOU WILL BE ASKED FOR ANOTHER. EVERYONE IS.',
  'achievements.two_titles': 'Two titles',
  'achievements.win_a_second_beast_bowl': 'Win a second Beast Bowl.',
  'achievements.the_board_has_opened_a_file': 'THE BOARD HAS OPENED A FILE. IT DOES THIS RARELY.',
  'achievements.a_league_award': 'A league award',
  'achievements.have_one_of_your_monsters_win': 'Have one of your monsters win a league award.',
  'achievements.one_of_yours_took_a_league': 'One of yours took a league award. {awardLine}',
  'achievements.every_other_gm_in_the_league': 'Every other GM in the league just looked up what you’re paying him. So did his agent. Enjoy the ceremony; the renewal comes after.',
  'achievements.ten_wins': 'Ten wins',
  'achievements.reach_10_career_wins': 'Reach 10 career wins.',
  'achievements.ten_career_wins_a_number_nobody': 'Ten career wins. A number nobody puts on a plaque, but it’s the one where I stop expecting a GM to disappear.',
  'achievements.thirty_wins': 'Thirty wins',
  'achievements.reach_30_career_wins': 'Reach 30 career wins.',
  'achievements.thirty_thats_the_hall_of_fame': 'Thirty. That’s the Hall of Fame line on Rookie, and a third of the way on All-Star. Either way, you’ve outlasted most of the people who sat where you sit.',
  'achievements.fifty_wins': 'Fifty wins',
  'achievements.reach_50_career_wins': 'Reach 50 career wins.',
  'achievements.fifty_i_pulled_the_file_four': 'Fifty. I pulled the file: four GMs in league history reached fifty with one club. Two of them were fired within two years of it. The Board has a long memory and a short patience.',
  'achievements.a_legend_track': 'A Legend Track',
  'achievements.choose_your_first_legend_track': 'Choose your first Legend Track.',
  'achievements.a_legend_track_you_understand_what': 'A Legend Track. You understand what you’ve started: three of those on one name and a monster no club has ever held walks into your region.',
  'achievements.the_other_gms_will_try_to': 'The other GMs will try to win the next two Beast Bowls just to stop you. I would.',
  'achievements.a_legend_unlocked': 'A legend unlocked',
  'achievements.unlock_a_legendary_monster_three_legend': 'Unlock a legendary monster (three Legend Tracks on one).',
  'achievements.a_legendary_monster_is_now_within': 'A LEGENDARY MONSTER IS NOW WITHIN YOUR REACH. NONE HAS BEEN SIGNED IN LIVING MEMORY.',
  'achievements.the_board_will_be_watching_the': 'THE BOARD WILL BE WATCHING THE {REGION} SCOUTING REPORTS.',
  'achievements.the_hall_of_fame': 'The Hall of Fame',
  'achievements.qualify_for_the_hall_of_fame': 'Qualify for the Hall of Fame.',
  'achievements.the_board_has_reviewed_your_record': 'THE BOARD HAS REVIEWED YOUR RECORD. YOU ARE ELIGIBLE FOR THE HALL OF FAME.',
  'achievements.the_door_is_open_you_may': 'THE DOOR IS OPEN. YOU MAY WALK THROUGH IT WHENEVER YOU CHOOSE. YOU MAY ALSO KEEP WORKING; THE BOARD HAS NO OPINION ON WHICH. IT HAS NEVER WRITTEN THIS LETTER TO THE SAME NAME TWICE.',
  'achievements.off_the_hot_seat': 'Off the hot seat',
  'achievements.meet_the_boards_goal_while_on': 'Meet the Board’s goal while on the hot seat.',
  'achievements.you_were_one_miss_from_a': 'You were one miss from a conversation nobody enjoys. You didn’t miss.',
  'achievements.for_what_its_worth_and_in': 'For what it’s worth, and in this office it isn’t worth much, I’d have kept you. The Board would not have asked.',
  'achievements.the_phone_works': 'The phone works',
  'achievements.make_your_first_trade': 'Make your first trade.',
