  'plays.play_action_pa_boot_pa_post': 'Play action (PA Boot, PA Post) and vertical shots (Three Verticals): the robber leaves the deep left to one late safety.',
  'plays.against_a_run_first_offense_that': 'Against a run-first offense that lives on fakes.',
  'plays.the_whole_front_stays_inside_elderoots': 'The whole front stays inside Elderoot’s grove: nobody bites on play action or misdirection.',
  'plays.toss_sweep_qb_draw_inside_zone': 'Toss Sweep, QB Draw, Inside Zone and play action that needs a bite.',
